const DEFAULT_PALETTE = [
    '#ffffff', '#000000', '#3b82f6', '#ef4444', 
    '#10b981', '#f59e0b', '#8b5cf6', '#ec4899'
];

let savedPalette = null;
try {
    const raw = localStorage.getItem('ingressoIdealPalette');
    if (raw && raw !== 'undefined') {
        savedPalette = JSON.parse(raw);
    }
} catch (e) {
    console.error("Erro ao carregar a paleta do localStorage:", e);
}

window.colorPalette = Array.isArray(savedPalette) ? savedPalette : [...DEFAULT_PALETTE];

function savePaletteToStorage() {
    localStorage.setItem('ingressoIdealPalette', JSON.stringify(window.colorPalette));
}

function applyColorToSelected(color) {
    const activeObj = canvas.getActiveObject();
    if (!activeObj) return;
    
    if (activeObj.type === 'activeSelection') {
        const objects = activeObj.getObjects();
        objects.forEach(obj => {
            if (obj.type === 'i-text' || obj.type === 'text' || obj.type === 'rect' || obj.type === 'circle') {
                obj.set('fill', color);
            }
        });
    } else {
        if (activeObj.type === 'i-text' || activeObj.type === 'text' || activeObj.type === 'rect' || activeObj.type === 'circle') {
            activeObj.set('fill', color);
        }
    }
    
    canvas.requestRenderAll();
    
    // Atualiza os inputs correspondentes
    const fontColorInput = document.getElementById('prop-font-color');
    if (fontColorInput) fontColorInput.value = color;
    
    const shapeColorInput = document.getElementById('prop-shape-color');
    if (shapeColorInput) shapeColorInput.value = color;
    
    saveHistory();
}

function renderColorPalette() {
    const paletteContainer = document.getElementById('color-palette');
    if (!paletteContainer) return;
    
    paletteContainer.innerHTML = '';
    
    window.colorPalette.forEach((color, idx) => {
        const swatch = document.createElement('div');
        swatch.className = 'color-swatch';
        swatch.style.backgroundColor = color;
        swatch.title = `Aplicar cor: ${color}`;
        
        swatch.addEventListener('click', () => {
            applyColorToSelected(color);
        });
        
        const removeBtn = document.createElement('button');
        removeBtn.className = 'remove-swatch';
        removeBtn.innerHTML = 'Ã—';
        removeBtn.title = 'Remover cor';
        
        removeBtn.addEventListener('click', (e) => {
            e.stopPropagation(); // Previne aplicar a cor ao remover
            window.colorPalette.splice(idx, 1);
            savePaletteToStorage();
            renderColorPalette();
        });
        
        swatch.appendChild(removeBtn);
        paletteContainer.appendChild(swatch);
    });
}

// Inicializa os botÃµes de adiÃ§Ã£o de cor da paleta
