// SISTEMA DE DESFAZER (UNDO / CTRL+Z)
// ==========================================
window.undoStack = [];
const MAX_HISTORY = 20;
window.isHistoryAction = false;

// Salva o estado atual no histÃ³rico
function saveHistory() {
    if (window.isHistoryAction) return;
    
    const state = JSON.stringify({
        pagesCount: pagesCount,
        pageNames: [...window.pageNames],
        canvasData: canvas.toJSON(['id', '_isTemplate'])
    });
    
    // Evita duplicar o Ãºltimo estado salvo
    if (window.undoStack.length > 0 && window.undoStack[window.undoStack.length - 1] === state) {
        return;
    }
    
    window.undoStack.push(state);
    
    if (window.undoStack.length > MAX_HISTORY) {
        window.undoStack.shift(); // Limita a 20 passos no histÃ³rico
    }
}

// Desfaz a Ãºltima aÃ§Ã£o
function undo() {
    if (window.undoStack.length <= 1) return;
    
    window.undoStack.pop();
    const previousState = window.undoStack[window.undoStack.length - 1];
    
    window.isHistoryAction = true;
    
    try {
        const data = JSON.parse(previousState);
        pagesCount = data.pagesCount || 1;
        window.pageNames = data.pageNames || [];
        
        if (pagesCount > 1) {
            canvas.setHeight((totalHeightPx * pagesCount) + (PAGE_GAP_PX * (pagesCount - 1)));
        } else {
            canvas.setHeight(totalHeightPx);
        }
        
        canvas.loadFromJSON(data.canvasData, function() {
            const objs = canvas.getObjects();
            const loadedCutLine = objs.find(o => o.id === 'cutLine');
            const loadedSafeLine = objs.find(o => o.id === 'safeLine');
            if (loadedCutLine) Object.assign(cutLine, loadedCutLine);
            if (loadedSafeLine) Object.assign(safeLine, loadedSafeLine);
            
            updatePageNamesUI();
            updateDeleteInput();
            enforceTemplatesAtBottom();
            selectPage(Math.min(window.selectedPageNumber, pagesCount)); // Restaura a seleÃ§Ã£o de pÃ¡gina correta
            canvas.requestRenderAll();
            
            window.isHistoryAction = false;
        });
    } catch(err) {
        console.error("Erro ao desfazer:", err);
        window.isHistoryAction = false;
    }
}

// Ouvintes automÃ¡ticos para camadas e salvamento de histÃ³rico
canvas.on('mouse:down', (options) => {
    // Determina a pÃ¡gina clicada com base no eixo Y do clique
    const pointer = canvas.getPointer(options.e);
    const clickY = pointer.y;
    const pageIndex = Math.floor(clickY / (totalHeightPx + PAGE_GAP_PX));
    const pageNum = pageIndex + 1;
    if (pageNum >= 1 && pageNum <= pagesCount) {
        selectPage(pageNum);
    }
});

