canvas.on('object:moving', function(e) {
    // Se a tecla SHIFT estiver pressionada, travar no eixo X (mantÃ©m o Y original daquele movimento)
    if (e.e && e.e.shiftKey && e.transform && e.transform.original) {
        e.target.set('top', e.transform.original.top);
    }
    updateGlobalProperties(e);
});
