// Modificando via inputs do painel
function applyProperties() {
    const obj = canvas.getActiveObject();
    if (!obj) return;
    
    const valX = parseFloat(inputX.value);
    const valY = parseFloat(inputY.value);
    const valW = parseFloat(inputW.value);
    const valH = parseFloat(inputH.value);
    
    if (!isNaN(valX)) obj.set('left', mmToPx(valX));
    if (!isNaN(valY)) obj.set('top', mmToPx(valY));
    
    if (!isNaN(valW) && valW > 0) {
        obj.set('scaleX', mmToPx(valW) / obj.width);
    }
    if (!isNaN(valH) && valH > 0) {
        obj.set('scaleY', mmToPx(valH) / obj.height);
    }
    
    canvas.requestRenderAll();
}

