// EXPORTAÇÃO IMAGENS (PNG e JPG)
function downloadImage(format) {
    const activePage = window.selectedPageNumber || 1;
    const pageTop = (activePage - 1) * (totalHeightPx + PAGE_GAP_PX);

    // Listas para rastrear o estado original de visibilidade dos objetos modificados
    const visibilityStates = [];

    // Esconder todas as guias visíveis E templates temporariamente
    canvas.getObjects().forEach(obj => {
        const isGuide = obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine'));
        const isTemplate = obj._isTemplate;
        if (isGuide || isTemplate) {
            visibilityStates.push({ obj: obj, wasVisible: obj.visible });
            obj.set('visible', false);
        }
    });
    
    // Se for JPG, garantir que o fundo seja branco para evitar que a transparência fique preta
    const originalBg = canvas.backgroundColor;
    if (format === 'jpeg') {
        canvas.backgroundColor = '#ffffff';
    }
    
    canvas.requestRenderAll();
    
    try {
        const dataUrl = canvas.toDataURL({
            format: format,
            quality: 1,
            multiplier: 1, // mantém a proporção do DPI original
            left: 0,
            top: Math.round(pageTop),
            width: Math.round(totalWidthPx),
            height: Math.round(totalHeightPx)
        });
        
        // Gera nome de arquivo limpo usando o nome da página selecionada
        const pageName = window.pageNames[activePage - 1];
        const cleanName = pageName && pageName.trim() ? pageName.trim().replace(/[^a-zA-Z0-9_\-]/g, '_') : `Pulseira_${activePage}`;
        const fileName = cleanName;
        
        // Criar link invisível e baixar
        const a = document.createElement('a');
        a.href = dataUrl;
        a.download = `${fileName}.${format === 'jpeg' ? 'jpg' : 'png'}`;
        a.click();
    } catch (err) {
        console.error("Erro ao gerar imagem do canvas:", err);
        alert("Erro ao exportar imagem: " + err.message + "\n\nPossível falha de segurança de CORS (origem das imagens importadas). Se você estiver abrindo o arquivo localmente pelo navegador (protocolo file://), tente rodar através de um servidor local (ex: Live Server) ou use imagens locais carregadas diretamente do seu computador.");
    } finally {
        // Restaurar visibilidade original das guias e templates
        visibilityStates.forEach(state => {
            state.obj.set('visible', state.wasVisible);
        });
        canvas.backgroundColor = originalBg;
        canvas.requestRenderAll();
    }
}

document.getElementById('btn-export-png').addEventListener('click', () => downloadImage('png'));
document.getElementById('btn-export-jpg').addEventListener('click', () => downloadImage('jpeg'));

// EXPORTAÇÃO PDF (Em Alta Resolução - Múltiplas Páginas)
document.getElementById('btn-export').addEventListener('click', async () => {
    alert("Iniciando exportação do PDF. Aguarde...");
    
    // Listas para rastrear o estado original de visibilidade dos objetos modificados
    const visibilityStates = [];

    // Esconder todas as guias visíveis e templates
    canvas.getObjects().forEach(obj => {
        const isGuide = obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine'));
        const isTemplate = obj._isTemplate;
        if (isGuide || isTemplate) {
            visibilityStates.push({ obj: obj, wasVisible: obj.visible });
            obj.set('visible', false);
        }
    });
    canvas.requestRenderAll();
    
    try {
        const { jsPDF } = window.jspdf;
        const pdfWidthMM = paperWidthMM + (bleedMM * 2);
        const pdfHeightMM = paperHeightMM + (bleedMM * 2);
        
        const doc = new jsPDF({
            orientation: pdfWidthMM > pdfHeightMM ? 'l' : 'p',
            unit: 'mm',
            format: [pdfWidthMM, pdfHeightMM]
        });
        
        // Loop pelas "páginas" cortando as fatias do Canvas
        for (let i = 0; i < pagesCount; i++) {
            // Extrai a fatia respectiva daquela página pulando o gap
            const dataUrl = canvas.toDataURL({
                format: 'png',
                quality: 1,
                multiplier: 1,
                left: 0,
                top: Math.round(i * (totalHeightPx + PAGE_GAP_PX)),
                width: Math.round(totalWidthPx),
                height: Math.round(totalHeightPx)
            });
            
            if (i > 0) doc.addPage();
            doc.addImage(dataUrl, 'PNG', 0, 0, pdfWidthMM, pdfHeightMM);
        }
        
        // Gera nome de arquivo limpo usando os nomes das páginas com fallback para vazios
        const cleanNames = window.pageNames.map((n, idx) => {
            const val = n ? n.trim() : '';
            return val ? val.replace(/[^a-zA-Z0-9_\-]/g, '_') : `Pulseira_${idx + 1}`;
        });
        const pdfName = cleanNames.join('_');
        
        // Baixar o PDF
        doc.save(`${pdfName}.pdf`);
        alert("Exportação concluída! O PDF com todas as páginas está nos seus Downloads.");
    } catch (err) {
        console.error("Erro ao gerar PDF:", err);
        alert("Erro ao exportar PDF: " + err.message + "\n\nPossível falha de segurança de CORS (origem das imagens importadas). Se você estiver abrindo o arquivo localmente pelo navegador (protocolo file://), tente rodar através de um servidor local (ex: Live Server) ou use imagens locais carregadas diretamente do seu computador.");
    } finally {
        // Restaurar visibilidade original das guias e templates
        visibilityStates.forEach(state => {
            state.obj.set('visible', state.wasVisible);
        });
        canvas.requestRenderAll();
    }
});

