const btnImportProject = document.getElementById('btn-import-project');
const inputImportProject = document.getElementById('project-import-upload');

if (btnImportProject && inputImportProject) {
    btnImportProject.addEventListener('click', () => {
        inputImportProject.click();
    });
    
    inputImportProject.addEventListener('change', function(e) {
        const file = e.target.files[0];
        if (!file) return;
        
        const reader = new FileReader();
        reader.onload = function(f) {
            try {
                const data = JSON.parse(f.target.result);
                
                let pagesCountB = 1;
                let pageNamesB = ["Pulseira Importada"];
                let galleryImagesB = [];
                let objectsToImport = [];
                
                if (data.version === 3 && data.canvasData) {
                    pagesCountB = data.pagesCount || 1;
                    pageNamesB = data.pageNames || [];
                    galleryImagesB = data.galleryImages || [];
                    objectsToImport = data.canvasData.objects || [];
                } else if (data.version === 2 && data.pages) {
                    pagesCountB = 1;
                    pageNamesB = ["Pulseira Importada"];
                    galleryImagesB = [];
                    objectsToImport = data.pages[0].objects || [];
                } else {
                    pagesCountB = 1;
                    pageNamesB = ["Pulseira Importada"];
                    galleryImagesB = [];
                    objectsToImport = data.objects || [];
                }
                
                // Mesclar imagens da galeria evitando duplicatas
                if (!window.galleryImages) window.galleryImages = [];
                galleryImagesB.forEach(imgB => {
                    const srcB = typeof imgB === 'string' ? imgB : imgB.src;
                    const exists = window.galleryImages.some(existing => {
                        const existingSrc = typeof existing === 'string' ? existing : existing.src;
                        return existingSrc === srcB;
                    });
                    if (!exists) {
                        window.galleryImages.push(imgB);
                    }
                });
                updateGalleryUI();
                
                // Mesclar paleta de cores do projeto importado
                if (data.colorPalette) {
                    data.colorPalette.forEach(col => {
                        if (!window.colorPalette.includes(col)) {
                            window.colorPalette.push(col);
                        }
                    });
                    savePaletteToStorage();
                    renderColorPalette();
                }
                
                const N_A = pagesCount; // PÃ¡ginas existentes no projeto ativo
                const N_B = pagesCountB; // PÃ¡ginas no projeto importado
                const targetPagesCount = N_A + N_B;
                
                // Ajusta a altura total do canvas Fabric.js para caber as novas pÃ¡ginas
                canvas.setHeight((totalHeightPx * targetPagesCount) + (PAGE_GAP_PX * (targetPagesCount - 1)));
                
                // Apensa os nomes das pÃ¡ginas do projeto importado
                for (let i = 0; i < N_B; i++) {
                    const originalName = pageNamesB[i] || "";
                    window.pageNames.push(originalName);
                }
                
                // Calcula o offset Y para as novas pÃ¡ginas importadas
                const yOffset = (totalHeightPx + PAGE_GAP_PX) * N_A;
                
                // Filtra objetos importados para ignorar as linhas de guias padrÃ£o (cutLine/safeLine)
                // de modo a evitar duplicÃ¡-las de forma desnecessÃ¡ria, pois as criaremos dinamicamente.
                const filteredObjects = objectsToImport.filter(obj => {
                    if (obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine'))) {
                        return false;
                    }
                    return true;
                });
                
                // Cria as novas linhas de guias locais para as pÃ¡ginas importadas
                for (let p = N_A + 1; p <= targetPagesCount; p++) {
                    const pageYOffset = (totalHeightPx + PAGE_GAP_PX) * (p - 1);
                    const newCutLine = new fabric.Rect({
                        id: 'cutLine_p' + p,
                        left: mmToPx(bleedMM),
                        top: mmToPx(bleedMM) + pageYOffset,
                        width: mmToPx(paperWidthMM),
                        height: mmToPx(paperHeightMM),
                        fill: 'transparent',
                        stroke: 'rgba(0,0,0,0.3)',
                        strokeWidth: mmToPx(0.3),
                        selectable: false,
                        evented: false
                    });
                    
                    const newSafeLine = new fabric.Rect({
                        id: 'safeLine_p' + p,
                        left: mmToPx(bleedMM + safeMarginMM),
                        top: mmToPx(bleedMM + safeMarginMM) + pageYOffset,
                        width: mmToPx(paperWidthMM - (safeMarginMM*2)),
                        height: mmToPx(paperHeightMM - (safeMarginMM*2)),
                        fill: 'transparent',
                        stroke: 'rgba(239, 68, 68, 0.6)',
                        strokeWidth: mmToPx(0.3),
                        strokeDashArray: [mmToPx(2), mmToPx(2)],
                        selectable: false,
                        evented: false,
                        visible: false
                    });
                    
                    canvas.add(newCutLine, newSafeLine);
                }
                
                // Desserializa os objetos filtrados do projeto B e os posiciona deslocados verticalmente
                fabric.util.enlivenObjects(filteredObjects, function(enlivenedObjects) {
                    enlivenedObjects.forEach(obj => {
                        // Desloca o objeto verticalmente
                        obj.set({
                            top: obj.top + yOffset
                        });
                        
                        // Atualiza IDs de templates se houver
                        if (obj.id && obj.id.startsWith('template_bg_p')) {
                            const originalPageNum = parseInt(obj.id.split('_p')[1]) || 1;
                            const newPageNum = N_A + originalPageNum;
                            obj.set({
                                id: 'template_bg_p' + newPageNum,
                                _isTemplate: true,
                                selectable: false,
                                evented: false
                            });
                        }
                        
                        // Atualiza IDs normais associados a pÃ¡ginas
                        if (obj.id && obj.id.includes('_p')) {
                            const parts = obj.id.split('_p');
                            const baseId = parts[0];
                            const originalPageNum = parseInt(parts[1]) || 1;
                            const newPageNum = N_A + originalPageNum;
                            obj.set({
                                id: baseId + '_p' + newPageNum
                            });
                        }
                        
                        canvas.add(obj);
                    });
                    
                    // Garante que os templates fiquem sempre atrÃ¡s
                    enforceTemplatesAtBottom();
                    
                    // Atualiza a contagem global de pÃ¡ginas
                    pagesCount = targetPagesCount;
                    
                    // Atualiza interface lateral, limitadores de exclusÃ£o e seleciona a primeira pÃ¡gina importada
                    updatePageNamesUI();
                    updateDeleteInput();
                    selectPage(N_A + 1);
                    
                    // Salva histÃ³rico pÃ³s-importaÃ§Ã£o
                    saveHistory();
                    
                    // Limpa o seletor de arquivos para permitir nova importaÃ§Ã£o do mesmo arquivo
                    inputImportProject.value = '';
                });
                
            } catch(err) {
                alert("Erro ao importar o projeto.");
                console.error(err);
                inputImportProject.value = '';
            }
        };
        reader.readAsText(file);
    });
}

// ==========================================
// AÃ‡Ã•ES: DUPLICAR E DELETAR
// ==========================================

function deleteSelectedObjects() {
    const activeObjects = canvas.getActiveObjects();
    if (activeObjects.length) {
        canvas.discardActiveObject();
        activeObjects.forEach(function(object) {
            // Impedir que as guias de impressÃ£o sejam deletadas
            if (object !== cutLine && object !== safeLine) {
                canvas.remove(object);
            }
        });
    }
}

function duplicateSelectedObject() {
    const activeObject = canvas.getActiveObject();
    if (!activeObject || activeObject === cutLine || activeObject === safeLine) return;

    activeObject.clone(function(cloned) {
        // MantÃ©m Y original. X = posiÃ§Ã£o original + largura do objeto + 10mm
        const objWidth = activeObject.getScaledWidth();
        const gap = mmToPx(10);
        
        cloned.set({
            left: activeObject.left + objWidth + gap,
            top: activeObject.top,
            evented: true,
        });

        if (cloned.type === 'activeSelection') {
            // Se for mÃºltiplos objetos agrupados, Ã© necessÃ¡rio clonar em massa
            cloned.canvas = canvas;
            cloned.forEachObject(function(obj) {
                canvas.add(obj);
            });
            cloned.setCoords();
        } else {
            canvas.add(cloned);
        }
        
        // MantÃ©m guias de impressÃ£o no topo absoluto
        canvas.bringToFront(cutLine);
        canvas.bringToFront(safeLine);
        
        // Seleciona o novo objeto duplicado
        canvas.setActiveObject(cloned);
        canvas.requestRenderAll();
    });
}

// Centralizar Objetos Selecionados na Altura da PÃ¡gina
function alignSelectedObjectsCenterY() {
    const activeObject = canvas.getActiveObject();
    if (!activeObject) return;

    const centerObject = (obj) => {
        // Ignora guias de impressÃ£o e margem de seguranÃ§a
        if (obj === cutLine || obj === safeLine || (obj.id && (obj.id.startsWith('cutLine') || obj.id.startsWith('safeLine')))) {
            return;
        }

        const cy = obj.getCenterPoint().y;
        const pageIndex = Math.floor(cy / (totalHeightPx + PAGE_GAP_PX));
        const pageTop = pageIndex * (totalHeightPx + PAGE_GAP_PX);
        const pageCenterY = pageTop + totalHeightPx / 2;

        if (obj.originY === 'center') {
            obj.set('top', pageCenterY);
        } else if (obj.originY === 'top') {
            obj.set('top', pageCenterY - (obj.getScaledHeight() / 2));
        } else if (obj.originY === 'bottom') {
            obj.set('top', pageCenterY + (obj.getScaledHeight() / 2));
        }
        obj.setCoords();
    };

    if (activeObject.type === 'activeSelection') {
        const objects = [...activeObject.getObjects()];
        canvas.discardActiveObject();
        objects.forEach(obj => centerObject(obj));
        const sel = new fabric.ActiveSelection(objects, {
            canvas: canvas
        });
        canvas.setActiveObject(sel);
    } else {
        centerObject(activeObject);
    }
    canvas.requestRenderAll();
    
    // Atualiza o painel de propriedades
    updateGlobalProperties({ selected: [canvas.getActiveObject()] });
}

// Ligar funÃ§Ãµes aos BotÃµes da UI
document.getElementById('btn-delete').addEventListener('click', deleteSelectedObjects);
document.getElementById('btn-duplicate').addEventListener('click', duplicateSelectedObject);
document.getElementById('btn-align-center-y').addEventListener('click', alignSelectedObjectsCenterY);

// Ligar funÃ§Ãµes aos Atalhos de Teclado
window.addEventListener('keydown', function(e) {
    // Evitar apagar elementos caso o usuÃ¡rio esteja editando os campos de input da barra lateral
    if (e.target.tagName.toLowerCase() === 'input' || e.target.tagName.toLowerCase() === 'textarea') return;
    
    // Evitar apagar texto se o usuÃ¡rio estiver editando "por dentro" do i-text no canvas
    const obj = canvas.getActiveObject();
    if (obj && obj.isEditing) return;

    // Inicia digitaÃ§Ã£o imediata ao comeÃ§ar a digitar em um bloco de texto selecionado
    if (obj && (obj.type === 'i-text' || obj.type === 'text') && e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        // Entra no modo de ediÃ§Ã£o
        obj.enterEditing();
        
        // Sobrescreve o texto com a tecla digitada
        obj.text = e.key;
        
        // Coloca o cursor no final do primeiro caractere
        obj.selectionStart = 1;
        obj.selectionEnd = 1;
        
        canvas.requestRenderAll();
        return; // Sai do keydown para nÃ£o disparar outros atalhos
    }

    // Delete ou Backspace para apagar
    if (e.key === 'Delete' || e.key === 'Backspace') {
        deleteSelectedObjects();
    }
    
    // Ctrl + D para Duplicar
    if ((e.ctrlKey || e.metaKey) && e.key === 'd') {
        e.preventDefault(); // Evita a funÃ§Ã£o de "Adicionar aos Favoritos" padrÃ£o do Chrome
        duplicateSelectedObject();
    }

    // Tecla E para Centralizar na Altura da PÃ¡gina
    if (e.key === 'e' || e.key === 'E') {
        e.preventDefault();
        alignSelectedObjectsCenterY();
    }

    // Ctrl + Z para Desfazer
    if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        undo();
    }
});

