function applyDefaultTemplateToPage(pageNum) {
    const templateId = 'template_bg_p' + pageNum;
    
    // Verifica se jÃ¡ existe algum template nessa pÃ¡gina para nÃ£o sobrescrever
    const existingBg = canvas.getObjects().find(o => o.id === templateId);
    if (existingBg) return;
    
    const url = 'modelo1.jpg'; // Gabarito base padrÃ£o
    fabric.Image.fromURL(targetUrl, function(img) {
        if (!img) return;
        
        // Escala para preencher toda a Ã¡rea da pulseira exata
        const scaleX = totalWidthPx / img.width;
        const scaleY = totalHeightPx / img.height;
        
        img.set({
            id: templateId,
            left: 0,
            top: (pageNum - 1) * (totalHeightPx + PAGE_GAP_PX),
            scaleX: scaleX,
            scaleY: scaleY,
            selectable: false,
            evented: false,
            opacity: 0.5, // 50% de opacidade padrÃ£o
            _isTemplate: true
        });
        
        canvas.add(img);
        canvas.sendToBack(img);
        enforceTemplatesAtBottom();
        canvas.requestRenderAll();
    }, { crossOrigin: 'anonymous' });
}

